resource "cloudstack_network" "${myResourceName}" {
   name = "test-network"
   cidr = "10.0.0.0/16"
   network_offering = "Default Network"
   zone = "zone-1"
}

resource "ibm_lb" "${myResourceName}" {
   connections = 
   datacenter    = ""
   ha_enabled  = false
   dedicated = true
}

resource "fastly_service_v1" "${myResourceName}" {
   name = "my-${myResourceName}"
   description = "my-description-${myResourceName}"

   domain {
       name    = "demo.notexample.com"
       comment = "demo"
   }

   backend {
       address = "127.0.0.1"
       name    = "localhost"
       port    = 80
   }

   force_destroy = true
}

resource "cloudstack_egress_firewall" "${myResourceName}" {
   network_id = "6eb22f91-7454-4107-89f4-36afcdf33021"

   rule {
       cidr_list = ["10.0.0.0/8"]
       protocol = "tcp"
       ports = ["80", "1000-2000"]
   }
}

data "aws_ebs_volume" "${ebs_volume}" {
    most_recent = true
    filter {
        name = "volume-type"
        values = ["gp2"]
    }
    filter {
        name = "tag:${Name}"
        values = ["${Example}"]
    }
}

resource "cloudstack_port_forward" "${myResourceName}" {
   ip_address_id = "30b21801-d4b3-4174-852b-0c0f30bdbbfb"

   forward {
       protocol = "tcp"
       private_port = 80
       public_port = 8080
       virtual_machine_id = "f8141e2f-4e7e-4c63-9362-986c908b7ea7"
   }
}

resource "azurerm_cdn_endpoint" "${MyResource}" {
   name = "example-name"
   profile_name = "\${azurerm_cdn_profile.test.name}"
   location = "West US"
   resource_group_name = "\${azurerm_resource_group.test.name}"
}

provider "aws" {
   access_key = "AWS ACCESS KEY"
   secret_key = "AWS SECRET KEY"
   region = "AWS REGION"
}

resource "cloudstack_network_acl_rule" "${myResourceName}" {
   acl_id = "f3843ce0-334c-4586-bbd3-0c2e2bc946c6"]]

   rule {
       action = "allow"
       cidr_list = ["10.0.0.0/8"]
       protocol = "tcp"
       ports = ["80", "1000-2000"]
       traffic_type = "ingress"
   }
}

resource "cloudstack_security_group_rule" "${myResourceName}" {
   security_group_id = "e340b62b-fbc2-4081-8f67-e40455c44bce"

   rule {
       cidr_list = ["0.0.0.0/0"]
       protocol  = "tcp"
       ports     = ["80", "443"]
   }

   rule {
       cidr_list                = ["192.168.0.0/24", "192.168.1.0/25"]
       protocol                 = "tcp"
       ports                    = ["80-90", "443"]
       traffic_type             = "egress"
       user_security_group_list = ["group01", "group02"]
   }
}

resource "azurerm_cdn_profile" "${MyResource}" {
   name = "example-name"
   location = "West US"
   sku = "Standard_Verizon"
   resource_group_name = "\${azurerm_resource_group.test.name}"
}

resource "azurerm_dns_mx_record" "${MyResource}" {
   name = "example-name"
   zone_name = "\${azurerm_dns_zone.test.name}"
   resource_group_name = "\${azurerm_resource_group.test.name}"
   ttl = "300"

   record {
       preference = 10
       exchange = "mail1.contoso.com"
   }

   record {
       preference = 20
       exchange = "mail2.contoso.com"
   }
}

resource "aws_api_gateway_model|" "${MyDemoModel}" {
   rest_api_id = "\${aws_api_gateway_rest_api.MyDemoAPI.id}"
   name = "user"
   description = "a JSON schema"
   content_type = "application/json"
   schema = <<EOF
{
   "type": "object"
}
EOF
}

resource "azurerm_dns_ns_record" "${MyResource}" {
   name = "example-name"
   zone_name = "\${azurerm_dns_zone.test.name}"
   resource_group_name = "\${azurerm_resource_group.test.name}"
   ttl = "300"

   record {
       nsdname = "ns1.contoso.com"
   }

   record {
       nsdname = "ns2.contoso.com"
   }
}

resource "azurerm_dns_srv_record" "${MyResource}" {
   name = "example-name"
   zone_name = "\${azurerm_dns_zone.test.name}"
   resource_group_name = "\${azurerm_resource_group.test.name}"
   ttl = "300"

   record {
       priority = 1
       weight = 5
       port = 8080
       target = "target1.contoso.com"
   }
}

resource "kubernetes_secret" "${1:kubernetes_secret_id}" {
   metadata {
       name = "${2:my-metadata-name}"
   }

   data {
       username = "${3:admin}"
       password = "${4:P4ssw0rd}"
   }

   type = "${5:kubernetes.io/basic-auth}"
}

resource "azurerm_dns_txt_record" "${MyResource}" {
   name = "example-name"
   zone_name = "\${azurerm_dns_zone.test.name}"
   resource_group_name = "\${azurerm_resource_group.test.name}"
   ttl = "300"

   record {
       value = "google-site-authenticator"
   }

   record {
       value = "more site information here"
   }
}

resource "cloudstack_vpc" "${myResourceName}" {
   name = "my-${myResourceName}"
   cidr = "10.0.0.0/16"
   vpc_offering = "Default VPC Offering"
   zone = "zone-1"
}

resource "kubernetes_service" "${1:kubernetes_service_id}" {
   metadata {
       name = "${2:my-metadata-name}"
   }

   spec {
       selector {
           App = "${3:MyApp}"
       }
       session_affinity = "${4:ClientIP}"
       port {
           port        = ${5:8080}
           target_port = ${6:808080}
       }
       type = "${7:LoadBalancer}"
   }

}

data "terraform_remote_state" "${myBackend}" {
   backend = "s3"
   config {
       bucket = "terraform-state-prod"
       key = "network/terraform.tfstate"
       region = "us-east-1"
   }
}

resource "librato_alert" "${myResourceName}" {
   name = "my-${myResourceName}"
   description = "my-description-${myResourceName}"

   services = [ "\${librato_service.myservice.id}" ]
   condition {
       type = "above"
       threshold = 10
       metric_name = "librato.cpu.percent.idle"
   }
}

resource "librato_service" "${myResourceName}" {
   name = "my-${myResourceName}"
   description = "my-description-${myResourceName}"

   title = "Email the admins"
   type = "mail"
   settings = <<EOF
{
   "addresses": "admin@example.com"
}
EOF
}

resource "rabbitmq_exchange" "${myResourceName}" {
   name = "my-${myResourceName}"
   description = "my-description-${myResourceName}"

   vhost = "\${rabbitmq_permissions.guest.vhost}"
   settings {
       type = "fanout"
       durable = false
       auto_delete = true
   }
}

resource "cobbler_snippet" "${myResourceName}" {
   name = "my-${myResourceName}"
   description = "my-description-${myResourceName}"
   body = "<content of snippet>"
}

# Copies the file as the root user using SSH
provisioner "file" {
   source      = "conf/myapp.conf"
   destination = "/etc/myapp.conf"
   connection {
       type        = "ssh"
       user        = "root"
       password    = "samplePasswordHere"
   }
}

data "terraform_remote_state" "${myBackend}" {
   backend = "etcd"
   config {
       path = "path/to/terraform.tfstate"
       endpoints = "http://one:4001 http://two:4001"
   }
}
